<?php
declare(strict_types=1);
require_once __DIR__ . '/accounts_common.php';
$user=qbook_require_user();qbook_require_role($user,['ADMIN']);production_require_method('POST');$input=production_input();
accounts_endpoint(function() use($user,$input): array {$id=(int)($input['supplier_id']??0);if($id<=0)accounts_fail('SUPPLIER_REQUIRED');$db=production_db();return accounts_transaction($db,function() use($db,$user,$input,$id): array {$s=$db->prepare("SELECT * FROM qbook_suppliers WHERE id=? FOR UPDATE");$s->execute([$id]);$old=$s->fetch();if(!$old)accounts_fail('SUPPLIER_NOT_FOUND',404);$name=production_clean_text($input['canonical_name']??$old['canonical_name'],200,'SUPPLIER_REQUIRED');$normalized=accounts_normalized_name($name);$duplicate=$db->prepare("SELECT id FROM qbook_suppliers WHERE normalized_name=? AND id<>?");$duplicate->execute([$normalized,$id]);if($duplicate->fetch())accounts_fail('SUPPLIER_ALREADY_EXISTS',409);$active=array_key_exists('is_active',$input)?((bool)$input['is_active']?1:0):(int)$old['is_active'];$db->prepare("UPDATE qbook_suppliers SET canonical_name=?,normalized_name=?,contact_person=?,phone=?,email=?,address=?,supplier_type=?,is_active=?,updated_by=? WHERE id=?")->execute([$name,$normalized,production_clean_text($input['contact_person']??($old['contact_person']??''),200,'INVALID_CONTACT',false)?:null,production_clean_text($input['phone']??($old['phone']??''),80,'INVALID_PHONE',false)?:null,production_clean_text($input['email']??($old['email']??''),255,'INVALID_EMAIL',false)?:null,production_clean_text($input['address']??($old['address']??''),500,'INVALID_ADDRESS',false)?:null,production_clean_text($input['supplier_type']??($old['supplier_type']??''),100,'INVALID_SUPPLIER_TYPE',false)?:null,$active,(int)$user['id'],$id]);if(isset($input['alias'])){$alias=production_clean_text($input['alias'],200,'INVALID_SUPPLIER_ALIAS');$db->prepare("INSERT INTO qbook_supplier_aliases(supplier_id,alias_name,normalized_alias,created_by) VALUES(?,?,?,?)")->execute([$id,$alias,accounts_normalized_name($alias),(int)$user['id']]);}accounts_audit($db,$user,'SUPPLIER_UPDATED','SUPPLIER',$id,['before'=>['canonical_name'=>$old['canonical_name'],'is_active'=>(int)